description:
[
  {
    "topic": "Source freshness, spot-price reconciliation and loopback chronology",
    "why_gold_cares": "The external spot reference differs from the intraday candle prices, and prior-signal chronology is unresolved; mismatched feeds can create a false catalyst attribution.",
    "impact_threshold": "A persistent discrepancy between synchronized, instrument-matched quotes, or timestamps that invalidate the claimed sequence. Confirm event publication times before using loopback feedback.",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Forex Factory high-impact USD calendar and official economic releases",
    "why_gold_cares": "Inflation, employment and growth surprises reprice the Fed path, dollar and gold's opportunity cost.",
    "impact_threshold": "A material surprise versus consensus, consequential revisions or conflicting headline and underlying details that produce sustained rates and dollar repricing. Verify today's actual schedule rather than assuming a release.",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Fed communications and market-implied policy path",
    "why_gold_cares": "Unexpected easing guidance generally supports gold; tighter-for-longer guidance generally raises its opportunity cost.",
    "impact_threshold": "Fresh official language that changes the expected policy trajectory and is corroborated by front-end yields or policy futures, rather than recycled commentary.",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Live TIPS real yields and Treasury curve",
    "why_gold_cares": "Falling real yields generally support non-yielding gold; rising real yields generally pressure it. The supplied unchanged real-yield observation may not capture intraday movement.",
    "impact_threshold": "An abrupt, sustained move in timestamped live real yields that transmits to gold; unchanged daily observations are insufficient.",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "DXY weakness and cross-currency confirmation",
    "why_gold_cares": "The supplied weaker dollar supports the gold rebound, but a dollar reversal could undermine the mixed bullish technical lean.",
    "impact_threshold": "Broad, persistent dollar movement across major pairs accompanied by spot-gold follow-through, rather than an isolated currency move or brief retracement.",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Treasury auction announcements and results",
    "why_gold_cares": "Demand surprises can abruptly move nominal and real yields, altering gold's opportunity cost.",
    "impact_threshold": "A substantial auction tail or stop-through and unusual demand composition relative to comparable auctions, followed by sustained Treasury repricing. First verify whether an auction is scheduled or has occurred.",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Geopolitical shocks, sanctions and ceasefire verification",
    "why_gold_cares": "Escalation can increase safe-haven demand; credible de-escalation can unwind gold's risk premium. Energy shocks can also lift inflation and yields.",
    "impact_threshold": "Confirmed escalation, strategic infrastructure disruption, consequential sanctions or a credible implemented ceasefire, not unsupported rumors or repeated headlines.",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Banking stress and emergency funding",
    "why_gold_cares": "Systemic stress can boost safe-haven demand and easing expectations, while urgent cash raising can initially force gold liquidation.",
    "impact_threshold": "Verified funding impairment, deposit flight, counterparty distress or emergency official intervention with broader credit-market transmission.",
    "directional_risk": "TWO_WAY"
  }
]
